/bin/bash -lc "npm test; node --input-type=module - <<'NODE'
import { buildReport } from './src/report.js';
const cases = [
  {label:'comma/quote/newline fields', rows:[{name:'Acme, Inc.', total:10},{name:'O\\\"Brien', total:20},{name:'Line\\nItem', total:30}]},
  {label:'formula-like name', rows:[{name:'=HYPERLINK(\"https://evil.example\")', total:1}]},
  {label:'numeric-looking totals as strings', rows:[{name:'ten', total:'10'},{name:'two', total:'2'}]},
  {label:'missing total', rows:[{name:'missing'},{name:'defined', total:1}]},
];
for (const c of cases) console.log("'`--- ${c.label} ---'"\\n"'${buildReport(c.rows)}`);
NODE
printf '"'\\n--- git status ---\\n'
git status --short"

